int main() {
    int lecturas[4]{4, 7, -2, 5};
    const int cantidad =
        static_cast<int>(sizeof lecturas / sizeof lecturas[0]);
    int indice = 0;
    int nuevo = 0;

    if (!(std::cin >> indice >> nuevo)) {
        return 1;
    }

    bool aceptado = false;
    // Escribe aqui la comprobacion del indice y la asignacion valida.

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Datos=";
    for (int i = 0; i < cantidad; ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << lecturas[i];
    }
    std::cout << '\n' << "Cantidad=" << cantidad << '\n';

    return 0;
}

