    if (indice >= 0 && indice < cantidad) {
        lecturas[indice] = nuevo;
        aceptado = true;
    }

    std::cout << "Aceptado=" << aceptado << '\n';
    std::cout << "Datos=";
    for (int i = 0; i < cantidad; ++i) {
        if (i != 0) {
            std::cout << ' ';
        }
        std::cout << lecturas[i];
    }
    std::cout << '\n' << "Cantidad=" << cantidad << '\n';

    return 0;
}

#include <iostream>

int main() {
    int lecturas[4]{4, 7, -2, 5};
    const int cantidad =
        static_cast<int>(sizeof lecturas / sizeof lecturas[0]);
    const int ultimo = cantidad - 1;
    lecturas[ultimo] = lecturas[1];
    lecturas[1] = 0;

    std::cout << lecturas[1] << ':' << lecturas[ultimo] << ':'
              << cantidad;
    return 0;
}

